//! Round trip of every v3 reader fixture through [`PositionedGraph`].
//!
//! Fixtures live in `context-read/tests/fixtures/v3` (authoritative manifest
//! `scenarios.json`, generated by the `ngrams` oracle); they are read from
//! disk so the model tests need no dependency on `ngrams` or `legacy`.

use std::path::PathBuf;

use pretty_assertions::assert_eq;
use serde::Deserialize;

use crate::positioned::{
    PositionedGraph,
    diff,
    interchange::PositionedGraphSnapshot,
};

#[derive(Deserialize)]
struct Scenario {
    name: String,
}

fn v3_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../context-read/tests/fixtures/v3")
}

fn read(path: PathBuf) -> Vec<u8> {
    std::fs::read(&path).unwrap_or_else(|error| panic!("{}: {error}", path.display()))
}

/// Every manifest fixture, decoded and structurally validated.
fn fixtures() -> Vec<(String, PositionedGraphSnapshot)> {
    let scenarios: Vec<Scenario> =
        serde_json::from_slice(&read(v3_dir().join("scenarios.json"))).unwrap();
    assert!(!scenarios.is_empty());
    scenarios
        .into_iter()
        .map(|Scenario { name }| {
            let fixture: PositionedGraphSnapshot =
                serde_json::from_slice(&read(v3_dir().join(format!("{name}.json"))))
                    .unwrap_or_else(|error| panic!("{name}: {error}"));
            fixture
                .validate()
                .unwrap_or_else(|error| panic!("{name}: {error}"));
            (name, fixture)
        })
        .collect()
}

#[test]
fn v3_fixtures_round_trip_through_positioned_graph() {
    for (name, fixture) in fixtures() {
        let graph = PositionedGraph::<crate::BaseGraphKind>::from_interchange(&fixture.graph)
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        graph
            .validate()
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        assert_eq!(graph.vertex_count(), fixture.graph.vertices.len(), "{name}");
        let actual = graph.to_interchange();
        let difference = diff(&fixture.graph, &actual);
        assert!(difference.is_empty(), "{name}: {difference}");
        assert_eq!(actual, fixture.graph, "{name}");
    }
}

#[test]
fn content_reconstructs_from_compositions() {
    for (name, fixture) in fixtures() {
        let graph = PositionedGraph::<crate::BaseGraphKind>::from_interchange(&fixture.graph)
            .unwrap();
        for content in fixture.graph.vertices.keys() {
            let atoms: Vec<char> = content.chars().collect();
            let token = graph
                .find(&atoms)
                .unwrap_or_else(|| panic!("{name}: no vertex for {content:?}"));
            assert_eq!(token.width.0, atoms.len(), "{name}: {content:?}");
            assert_eq!(graph.content(token.index), Some(atoms), "{name}: {content:?}");
        }
    }
}
